CREATE OR REPLACE FUNCTION public.can_use_chat_audio(_name text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.chat_rooms r WHERE r.id::text=split_part(_name,'/',1) AND public.can_access_unified_chat(r.id,auth.uid()) AND (NOT _write OR (split_part(_name,'/',2)=auth.uid()::text AND r.merged_into_room_id IS NULL AND (r.participant_a IS NOT NULL OR r.is_operation)))); $$;
REVOKE ALL ON FUNCTION public.can_use_chat_audio(text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_use_chat_audio(text,boolean) TO authenticated;
CREATE POLICY chat_audio_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-audio' AND public.can_use_chat_audio(name,false));
CREATE POLICY chat_audio_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chat-audio' AND public.can_use_chat_audio(name,true));
CREATE POLICY chat_audio_read_guard ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'chat-audio' OR public.can_use_chat_audio(name,false));
CREATE POLICY chat_audio_anon_guard ON storage.objects AS RESTRICTIVE FOR SELECT TO anon USING(bucket_id<>'chat-audio');
CREATE POLICY chat_audio_upload_guard ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'chat-audio' OR public.can_use_chat_audio(name,true));
CREATE POLICY chat_audio_immutable ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id<>'chat-audio') WITH CHECK(bucket_id<>'chat-audio');
CREATE POLICY chat_audio_cleanup ON storage.objects FOR DELETE TO authenticated USING(bucket_id='chat-audio' AND public.can_use_chat_audio(name,true) AND NOT EXISTS(SELECT 1 FROM public.messages m WHERE m.metadata->>'audio_path'=name));
CREATE POLICY chat_audio_delete_guard ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'chat-audio' OR (public.can_use_chat_audio(name,true) AND NOT EXISTS(SELECT 1 FROM public.messages m WHERE m.metadata->>'audio_path'=name)));
CREATE OR REPLACE FUNCTION public.guard_chat_audio_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='audio' AND NEW.metadata ? 'audio_path' THEN IF NEW.sender_id IS DISTINCT FROM auth.uid() OR split_part(NEW.metadata->>'audio_path','/',1) IS DISTINCT FROM NEW.room_id::text OR NOT public.can_use_chat_audio(NEW.metadata->>'audio_path',true) OR NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='chat-audio' AND s.name=NEW.metadata->>'audio_path' AND s.metadata->>'mimetype' IN ('audio/webm','audio/ogg','audio/mp4','audio/wav')) THEN RAISE EXCEPTION 'Audio non autorisé'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_chat_audio_link BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_chat_audio_link();